/* Shared roster directory: stable IDs, bounded rows, and branch/team filters. */
let memberDirectory={search:'',branch:BPD_BRANCH_NAMES[0],role:'',status:'active',page:1,size:25};
function memberDirectoryRows(){const f=memberDirectory,q=f.search.trim().toLocaleLowerCase('id-ID');return memberList.filter(m=>(!q||[m.name,m.id].join(' ').toLocaleLowerCase('id-ID').includes(q))&&(!f.branch||(m.branches||[]).includes(f.branch))&&(!f.role||m.role===f.role)&&(f.status==='all'||(m.active!==false)===(f.status==='active'))&&(typeof dateRecordMatches!=='function'||dateRecordMatches('Member',m))).sort((a,b)=>(a.branches||[]).join().localeCompare((b.branches||[]).join())||a.role.localeCompare(b.role)||a.name.localeCompare(b.name,'id-ID')||a.id.localeCompare(b.id));}
function memberDirectorySet(key,value){memberDirectory[key]=value;if(key!=='page')memberDirectory.page=1;renderContent();if(key==='search'){const input=document.querySelector('#memberDirectorySearch');input?.focus();input?.setSelectionRange(value.length,value.length);}}
function memberDirectoryReset(){memberDirectory={search:'',branch:BPD_BRANCH_NAMES[0],role:'',status:'active',page:1,size:25};if(typeof dateFilterClear==='function')dateFilterClear('Member');renderContent();}
const memberDirectoryPrevious=memberScreen;
memberScreen=function(){
 if(authUser?.role!=='Superadmin'||activeBranch!==BPD_BRANCH_NAMES[0])return memberDirectoryPrevious();
 const f=memberDirectory,rows=memberDirectoryRows(),pages=Math.max(1,Math.ceil(rows.length/f.size));f.page=Math.min(Math.max(1,Number(f.page)||1),pages);const shown=rows.slice((f.page-1)*f.size,f.page*f.size),active=memberList.filter(m=>m.active!==false),routes=db.config.masters.escalation.aoRoutes||[],opt=(value,label,selected)=>'<option value="'+E(value)+'" '+(selected===value?'selected':'')+'>'+E(label)+'</option>',ao=active.filter(m=>m.role==='AO');
 let html=titleBlock('Member','Akun berdasarkan kantor penempatan. Kelola dari HQ Renon.',btn('Buat Member','memberForm()',true));
 html+='<section class="panel member-directory-tools" aria-label="Filter member"><label class="member-directory-search">Cari member<input id="memberDirectorySearch" type="search" placeholder="Nama atau User ID" value="'+E(f.search)+'" oninput="memberDirectorySet(\'search\',this.value)"></label><label>Cabang<select onchange="memberDirectorySet(\'branch\',this.value)">'+opt('','Semua cabang',f.branch)+BPD_BRANCH_NAMES.map(b=>opt(b,b,f.branch)).join('')+'</select></label><label>Role<select onchange="memberDirectorySet(\'role\',this.value)">'+opt('','Semua role',f.role)+['AO','SPV','Kepala Kantor','Manajemen Pusat','Superadmin'].map(r=>opt(r,r,f.role)).join('')+'</select></label><label>Status<select onchange="memberDirectorySet(\'status\',this.value)">'+[['active','Aktif'],['inactive','Nonaktif'],['all','Semua status']].map(([v,l])=>opt(v,l,f.status)).join('')+'</select></label>'+btn('Reset filter','memberDirectoryReset()')+'</section>';
 html+=(typeof dateFilterControls==='function'?dateFilterControls('Member','Tanggal akun dibuat'):'')+'<div class="listhead"><strong>'+rows.length+' member sesuai filter</strong><span>'+ao.length+' AO aktif di kantor operasional</span></div><div class="scrolltable member-directory-table"><table class="datatable membertable"><thead><tr><th>Nama / User ID</th><th>Role</th><th>Akses Cabang</th><th>Supervisor</th><th>Status</th><th>Aksi</th></tr></thead><tbody>'+shown.map(m=>{const route=routes.find(r=>r.aoId===m.id),spv=memberList.find(s=>s.id===route?.spvId&&s.role==='SPV'&&s.active!==false&&(m.branches||[]).some(b=>(s.branches||[]).includes(b)));return '<tr data-member-id="'+E(m.id)+'"><td data-label="Member"><strong>'+E(m.name)+'</strong><small>'+E(m.id)+'</small></td><td data-label="Role">'+E(m.role)+'</td><td data-label="Cabang">'+(m.branches||[]).map(b=>'<small>'+E(b)+'</small>').join('')+'</td><td data-label="Supervisor">'+E(m.role==='AO'?(spv?.name||'Belum dipetakan'):'—')+'</td><td data-label="Status">'+badge(m.active!==false?'Aktif':'Nonaktif')+'</td><td data-label="Aksi">'+btn('Edit',"memberForm('"+m.id+"')")+'</td></tr>';}).join('')+(shown.length?'':'<tr class="member-directory-empty"><td colspan="6">Tidak ada member sesuai filter.</td></tr>')+'</tbody></table></div>';
 html+='<nav class="member-directory-pager" aria-label="Halaman daftar member"><span>'+ (rows.length?((f.page-1)*f.size+1)+'–'+Math.min(f.page*f.size,rows.length):'0')+' dari '+rows.length+' member</span><div><button type="button" '+(f.page<=1?'disabled':'')+' onclick="memberDirectorySet(\'page\','+(f.page-1)+')">Sebelumnya</button><span>'+f.page+' / '+pages+'</span><button type="button" '+(f.page>=pages?'disabled':'')+' onclick="memberDirectorySet(\'page\','+(f.page+1)+')">Berikutnya</button></div></nav>';
 return html;
};
